<?php

namespace MongoDB\BSON;

use JsonSerializable;
use MongoDB\Driver\Exception\InvalidArgumentException;
use Stringable;

/**
 * <div id="class.mongodb-bson-decimal128" class="reference"> <h1 class="title">The MongoDB\BSON\Decimal128 class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.2.0)</p>  <div class="section" id="mongodb-bson-decimal128.intro">   <h2 class="title">简介</h2>   <p class="simpara">    BSON type for the    <a href="https://en.wikipedia.org/wiki/Decimal128_floating-point_format" class="link external">»&nbsp;Decimal128 floating-point format</a>,    which supports numbers with up to 34 decimal digits (i.e. significant    digits) and an exponent range of −6143 to +6144.   </p>   <p class="simpara">    Unlike the double BSON type (i.e. <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span> in PHP), which only    stores an approximation of the decimal values, the decimal data type stores    the exact value. For example, <span class="literal">MongoDB\BSON\Decimal128('9.99')</span>    has a precise value of 9.99 where as a double 9.99 would have an approximate    value of 9.9900000000000002131628….   </p>      <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">     <span class="classname"><strong class="classname">MongoDB\BSON\Decimal128</strong></span> is only compatible with     MongoDB 3.4+. Attempting to use the BSON type with an earlier version of     MongoDB will result in an error.    </span>   </p></blockquote>  </div>  <div class="section" id="mongodb-bson-decimal128.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\BSON\Decimal128</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-decimal128interface.php" class="interfacename">MongoDB\BSON\Decimal128Interface</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.mongodb-bson-type.php" class="interfacename">MongoDB\BSON\Type</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-decimal128.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>)</div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-decimal128.jsonserialize.php" class="methodname" style="color:#CC7832">jsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-decimal128.tostring.php" class="methodname" style="color:#CC7832">__toString</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">             <tr>        <td>PECL mongodb 2.0.0</td>        <td>         <span class="simpara">          此类不再实现 <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> 接口。         </span>        </td>       </tr>      <tr>       <td>PECL mongodb 1.12.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> for PHP 8.0+.       </td>      </tr>      <tr>       <td>PECL mongodb 1.3.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-decimal128interface.php" class="interfacename">MongoDB\BSON\Decimal128Interface</a></span>.       </td>      </tr>      <tr>       <td>PECL mongodb 1.2.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> and        <span class="interfacename"><a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a></span>.       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\BSON\Decimal128::__construct} — Construct a new Decimal128</li><li>{@link MongoDB\BSON\Decimal128::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link MongoDB\BSON\Decimal128::__toString} — Returns the string representation of this Decimal128</li></ul></div>
 * 
 * BSON type for the Decimal128 floating-point format, which supports numbers with up to 34 decimal digits (i.e. significant digits) and an exponent range of −6143 to +6144.
 * @link https://php.net/manual/zh/class.mongodb-bson-decimal128.php
 */
final class Decimal128 implements Type, Decimal128Interface, JsonSerializable, Stringable
{
    /**
 * <div id="mongodb-bson-decimal128.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Decimal128::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.2.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Decimal128::__construct</span> — <span class="dc-title">Construct a new Decimal128</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-decimal128.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Decimal128::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>)</div>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">     <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-decimal128.php" class="classname">MongoDB\BSON\Decimal128</a></span> is only compatible with     MongoDB 3.4+. Attempting to use the BSON type with an earlier version of     MongoDB will result in an error.    </span>   </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-decimal128.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">value</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      A decimal string.     </span>    </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-decimal128.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if <span class="parameter" style="color:#3A95FF">value</span> is not a valid decimal string.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-decimal128.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Decimal128::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>var_dump</span><span style="color: #007700">(new </span><span style="color: #9876AA">MongoDB\BSON\Decimal128</span><span style="color: #007700">(</span><span style="color: #9876AA">1234.5678</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(new </span><span style="color: #9876AA">MongoDB\BSON\Decimal128</span><span style="color: #007700">(</span><span style="color: #9876AA">NAN</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(new </span><span style="color: #9876AA">MongoDB\BSON\Decimal128</span><span style="color: #007700">(</span><span style="color: #9876AA">INF</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\BSON\Decimal128)#1&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["dec"]=&gt;<br>&nbsp;&nbsp;string(9)&nbsp;"1234.5678"<br>}<br>object(MongoDB\BSON\Decimal128)#1&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["dec"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"NaN"<br>}<br>object(MongoDB\BSON\Decimal128)#1&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["dec"]=&gt;<br>&nbsp;&nbsp;string(8)&nbsp;"Infinity"<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-decimal128.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://en.wikipedia.org/wiki/Decimal128_floating-point_format" class="link external">»&nbsp;Decimal128 floating-point format</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 * 
     * Construct a new Decimal128
     * @link https://php.net/manual/zh/mongodb-bson-decimal128.construct.php
     * @param string $value A decimal string.
     */
    final public function __construct(string $value = '') {}

    /**
 * <div id="mongodb-bson-decimal128.tostring" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Decimal128::__toString</h1>  <p class="verinfo">(mongodb &gt;=1.2.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Decimal128::__toString</span> — <span class="dc-title">Returns the string representation of this Decimal128</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-decimal128.tostring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Decimal128::__toString</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-decimal128.tostring-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-decimal128.tostring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the string representation of this Decimal128.  </p> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-decimal128.tostring-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Decimal128::__toString()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>var_dump</span><span style="color: #007700">((string) new </span><span style="color: #9876AA">MongoDB\BSON\Decimal128</span><span style="color: #007700">(</span><span style="color: #9876AA">1234.5678</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">((string) new </span><span style="color: #9876AA">MongoDB\BSON\Decimal128</span><span style="color: #007700">(</span><span style="color: #9876AA">NAN</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">((string) new </span><span style="color: #9876AA">MongoDB\BSON\Decimal128</span><span style="color: #007700">(</span><span style="color: #9876AA">INF</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(9)&nbsp;"1234.5678"<br>string(3)&nbsp;"NaN"<br>string(8)&nbsp;"Infinity"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-decimal128.tostring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://en.wikipedia.org/wiki/Decimal128_floating-point_format" class="link external">»&nbsp;Decimal128 floating-point format</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 * 
