    public static function __set_state(array $properties): self {}

    /**
 * <div id="mongodb-bson-decimal128.jsonserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Decimal128::jsonSerialize</h1>  <p class="verinfo">(mongodb &gt;=1.2.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Decimal128::jsonSerialize</span> — <span class="dc-title">Returns a representation that can be converted to JSON</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-decimal128.jsonserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Decimal128::jsonSerialize</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-decimal128.jsonserialize-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-decimal128.jsonserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns data which can be serialized by <span class="function">{@link json_encode()}</span> to   produce an extended JSON representation of the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-decimal128.php" class="classname">MongoDB\BSON\Decimal128</a></span>.  </p>    <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    The output is consistent with the <span class="function">{@link MongoDB\BSON\toJSON()}</span>    function, which uses the driver-specific legacy extended JSON format. This    does not necessarily match the    <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#relaxed-extended-json-example" class="link external">»&nbsp;relaxed</a>    or <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#canonical-extended-json-example" class="link external">»&nbsp;canonical</a>    extended JSON representations used by    <span class="function">{@link MongoDB\BSON\toRelaxedExtendedJSON()}</span> and    <span class="function">{@link MongoDB\BSON\toCanonicalExtendedJSON()}</span>, respectively.   </span>  </p></blockquote> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-decimal128.jsonserialize-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-decimal128.jsonserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link JsonSerializable::jsonSerialize()} - 指定需要被序列化成 JSON 的数据</span></li>   <li><span class="function">{@link json_encode()} - 对变量进行 JSON 编码</span></li>   <li><span class="function">{@link MongoDB\BSON\toCanonicalExtendedJSON()} - Returns the Canonical Extended JSON representation of a BSON value</span></li>   <li><span class="function">{@link MongoDB\BSON\toRelaxedExtendedJSON()} - Returns the Relaxed Extended JSON representation of a BSON value</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/mongodb-extended-json/" class="link external">»&nbsp;MongoDB Extended JSON</a></li>  </ul> </div></div>
